            for dl in [-1, 1]:
                neighbor = self.get_cell(row, col, l + dl)
                if neighbor: cell.neighbors.append(neighbor)

class TriGrid(Grid):
    def _configure_cells(self):
        for cell in self.each_cell():
            r, c, l = cell.row, cell.column, cell.level
