                ts, te = c * step - math.pi/2, (c + 1) * step - math.pi/2
                ox, oy = config.SCREEN_WIDTH / 2 + offset[0], (config.SCREEN_HEIGHT - self.top_margin + self.bottom_margin) / 2 + offset[1]

